const COLLECTION_ID = "default";
const OUTPUT_PATH = "/home/user/fixed_mint_response.json";

const apiKey = process.env.CROSSMINT_SERVER_KEY;

async function writeResponse(payload) {
  await fs.promises.writeFile(OUTPUT_PATH, JSON.stringify(payload, null, 2));
}

async function main() {
  if (!apiKey || !apiKey.startsWith("sk_")) {
    await writeResponse({
      error: "Missing or invalid CROSSMINT_SERVER_KEY. Expected a server-side key starting with sk_",
    });
    return;
  }

  const recipient = "email:user@example.com:polygon-amoy";
  const metadata = {
    name: "Demo NFT",
    description: "Minted with Crossmint API",
    image: "https://example.com/assets/demo-nft.png",
  };

  try {
    const response = await fetch(
      `${API_BASE_URL}v1-alpha1/minting/collections/${COLLECTION_ID}/nfts`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-client-secret": apiKey,
        },
        body: JSON.stringify({
          recipient,
          metadata,
        }),
      }
    );

    const responseJson = await response.json().catch(() => ({
      error: "Failed to parse response JSON",
      status: response.status,
    }));

    await writeResponse({
      status: response.status,
      ok: response.ok,
      data: responseJson,
    });
  } catch (error) {
    await writeResponse({
      error: "Request failed",
      details: error

